﻿using System;
using System.IO;
using System.Text;

namespace k_rounding
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            int n = Next();
            int k = Next();

            int nn = n;
            long ex = 1;
            while (n%10 == 0)
            {
                n /= 10;
                k--;
            }
            while (k > 0)
            {
                if (n%2 == 0)
                {
                    ex *= 5;
                    n /= 2;
                    k--;
                }
                else if (n%5 == 0)
                {
                    ex *= 2;
                    n /= 5;
                    k--;
                }
                else 
                    break;
            }
            while (k > 0)
            {
                ex *= 10;
                k--;
            }

            writer.WriteLine(ex*nn);
            writer.Flush();
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}
